import { createSlotSymbolCatalog, type SlotGameDefinition, type SlotSymbolDefinition } from '../models/SlotGameTypes';

const MULTIPLIER_VALUES = [2, 3, 4, 6, 8, 10, 12, 15, 18, 25, 50, 55, 60, 65, 80, 100, 150, 200, 250, 500] as const;

const NORMAL_SYMBOLS = [
    { id: 1, kind: 'normal', name: 'sym1', frame: 'symbol_h1' },
    { id: 2, kind: 'normal', name: 'sym2', frame: 'symbol_h2' },
    { id: 3, kind: 'normal', name: 'sym3', frame: 'symbol_h3' },
    { id: 4, kind: 'normal', name: 'sym4', frame: 'symbol_h4' },
    { id: 5, kind: 'normal', name: 'sym5', frame: 'symbol_l1' },
    { id: 6, kind: 'normal', name: 'sym6', frame: 'symbol_l2' },
    { id: 7, kind: 'normal', name: 'sym7', frame: 'symbol_l3' },
    { id: 8, kind: 'normal', name: 'sym8', frame: 'symbol_l4' },
    { id: 9, kind: 'normal', name: 'sym9', frame: 'symbol_l5' },
] satisfies readonly SlotSymbolDefinition[];

const SCATTER_SYMBOL = { id: 10, kind: 'scatter', name: 'scatter', frame: 'symbol_scatter' } satisfies SlotSymbolDefinition;
const JACKPOT_SYMBOL = { id: 1000, kind: 'jackpot', name: 'jackpot', frame: 'symbol_jackpot' } satisfies SlotSymbolDefinition;

const multiplierSymbols = (startId: number, upgradeable: boolean): SlotSymbolDefinition[] =>
    MULTIPLIER_VALUES.map((value, index) => ({
        id: startId + index,
        kind: 'multiplier',
        name: `mul${value}`,
        value,
        upgradeable,
        colorTier: 4 - Math.floor(index / 5),
        frame: ({ side, symbol }) => `symbol_m${side}_${symbol.colorTier}`,
    }));
export const SLOT_GAME_DEFINITION: SlotGameDefinition = {
    symbols: createSlotSymbolCatalog({
        symbols: [...NORMAL_SYMBOLS, SCATTER_SYMBOL, ...multiplierSymbols(11, false), ...multiplierSymbols(111, true), JACKPOT_SYMBOL],
        fallback: { kind: 'normal', name: 'unknown', frame: 'symbol_h1' },
    }),
};

/** 倍率球的 id 起點：11–30 不可升級、111–130 可升級，各 {@link MULTIPLIER_VALUES} 那麼多個 */
const MULTIPLIER_ID_BASE = 11;
const MULTIPLIER_UPGRADEABLE_ID_BASE = 111;

/**
 * 給演出邏輯共用的 ID 常數。
 *
 * @see SYMBOL_IDS.multiplierPool 為什麼倍率球只有一個池 id。
 */
export const SYMBOL_IDS = {
    normalMin: 1,
    normalMax: NORMAL_SYMBOLS.length,
    scatter: SCATTER_SYMBOL.id,
    jackpot: JACKPOT_SYMBOL.id,
    /**
     * 所有倍率球在物件池裡共用的 id。
     *
     * 40 個倍率球 id 共用同一支 `symbol_m` spine，長相差異全靠執行期設的 skin `m{side}_{tier}`，
     * 而 `side` 還不在 id 裡（由欄位決定）——所以「一個 id 一支 prefab」對倍率球不成立。池只認
     * 這一個 id，真正的長相由 `SymbolCell` 保存的 `SymbolExtras` 在租借後回填。
     */
    multiplierPool: MULTIPLIER_ID_BASE,
} as const;

/**
 * 這個 id 是不是倍率球。
 *
 * 用 id 範圍判斷而不是 `symbols.resolve(id).kind`，是為了讓建池與換圖這條每格都會走到的路徑
 * 不必每次去查表建物件。
 *
 * @param id 符號 id。
 * @returns 是倍率球時為 true。
 */
export function isMultiplierSymbolId(id: number): boolean {
    const count = MULTIPLIER_VALUES.length;
    return (
        (id >= MULTIPLIER_ID_BASE && id < MULTIPLIER_ID_BASE + count) ||
        (id >= MULTIPLIER_UPGRADEABLE_ID_BASE && id < MULTIPLIER_UPGRADEABLE_ID_BASE + count)
    );
}

/**
 * 全部倍率球的 id（11–30 與 111–130）。
 *
 * 給「圖名 → 符號 id」的反查表用：圖名由 `symbols.frameName(id, side)` 產生，反查只能靠
 * 正著走一遍所有 id。列在這裡而不是在 View 裡自己組字串，命名規則才只有這個檔案知道。
 */
export const MULTIPLIER_SYMBOL_IDS: readonly number[] = MULTIPLIER_VALUES.flatMap((_, index) => [
    MULTIPLIER_ID_BASE + index,
    MULTIPLIER_UPGRADEABLE_ID_BASE + index,
]);

// 符號縮放 一般符號 0.62 scatter jackpot 倍率球 0.5
const NORMAL_SYMBOL_SCALE = 0.62;
const SPECIAL_SYMBOL_SCALE = 0.5;

/** 符號的顯示縮放 靜態圖與動效共用 */
export function getSymbolScale(id: number): number {
    const special = id === SYMBOL_IDS.scatter || id === SYMBOL_IDS.jackpot || isMultiplierSymbolId(id);
    return special ? SPECIAL_SYMBOL_SCALE : NORMAL_SYMBOL_SCALE;
}
