import { sp } from 'cc';
import { GameTask } from './GameTask';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';
import { playCollectMulFly, resolveCollectFlyDuration } from '../ui/CollectMulEffect';
import { raceSkip, skipWait } from '../controllers/SkipWait';

interface IWinPerformStrategy<TGame> {
    play(game: TGame, ...args: unknown[]): Promise<void>;
    skip?(game: TGame): void;
    reset?(game: TGame): void;
}

const USE_COLLECT_FLY_EFFECT = true; // 切換版本
const ANIM_SEC = 0.67;
// 被跳過後進行中的流程不再往下
interface CollectAbort {
    aborted: boolean;
}
interface CollectBall {
    col: number;
    row: number;
    val: number;
}

/**
 * 收球演出 原 GameMain_1001.playCollectWin()，拆出來給 Net/Task 系列使用
 * winBarMulValue/winBarMulEntered/win-bar 動畫仍透過 game 呼叫回去
 * 這些欄位/方法同時被 GameMain_1001.resetWinBar() 使用 無法整批搬離 GameMain
 * */
export async function runCollectWin(
    game: ISlotGameMain<GameViewAdapter>,
    cols: number[][],
    acc: number,
    isFg: boolean,
    finalNum: number
): Promise<void> {
    const balls: CollectBall[] = [];

    for (let col = 0; col < cols.length; col++) {
        for (let row = 0; row < cols[col].length; row++) {
            const info = game.definition.symbols.resolve(cols[col][row]);

            if (info.kind === 'multiplier') {
                balls.push({ col, row, val: info.value });
            }
        }
    }

    if (balls.length === 0) return;

    const hasMulValue = isFg && game.winBarMulValue > 0;

    // 跳過 倍率與贏分直接到最終值
    const abort: CollectAbort = { aborted: false };
    const finishSkipped = (): void => {
        abort.aborted = true;
        game.forEachView((v) => {
            for (const b of balls) v.slotMachineView?.reelViews?.[b.col]?.playMultiplierCollect(b.row);
        });
        game.winBarMulValue = acc;
        game.setWinBarMul(acc);
        if (isFg) game.setTotalMultiplierLabel(acc);
        game.playWinBarAdd(finalNum);
    };

    // 收球前停一拍
    if (await skipWait(game, 0.45)) return finishSkipped();

    game.winBarMulEntered = false;

    const work = USE_COLLECT_FLY_EFFECT
        ? runCollectWinWithFlyEffect(game, balls, hasMulValue, acc, isFg, finalNum, abort)
        : runCollectWinWithArtAnimation(game, balls, hasMulValue, acc, isFg, finalNum, abort);
    if (await raceSkip(game, work)) return finishSkipped();

    // 收尾停留
    if (await skipWait(game, 1)) return;
}

/** 原美術 Spine 版本 */
async function runCollectWinWithArtAnimation(
    game: ISlotGameMain<GameViewAdapter>,
    balls: CollectBall[],
    hasMulValue: boolean,
    acc: number,
    isFg: boolean,
    finalNum: number,
    abort: CollectAbort
): Promise<void> {
    const lead = hasMulValue ? 1 : 0;
    // 三段速度各自額外加碼 一般快速急速分別是 1s 0.5s 0.2s 加在合併進總分前 讓最終倍率多停留一下
    const finishDelay = (balls.length + lead) * ANIM_SEC + 0.3 + game.cascadeTiming().mulHoldExtra;
    const tasks: Promise<void>[] = [];

    game.forEachView((v) => {
        const root = v.bg?.parent;
        const sk = root?.getChildByName('collect')?.getComponent(sp.Skeleton);
        const reels = v.slotMachineView?.reelViews;

        tasks.push(
            new Promise<void>((resolve) => {
                if (sk) {
                    sk.node.active = true;

                    if (hasMulValue) {
                        sk.setAnimation(0, 'mul', false);
                    }
                }

                balls.forEach((b, i) => {
                    const anim = `p${b.col + 1}_${b.row + 1}`;

                    if (sk) {
                        if (i === 0 && !hasMulValue) {
                            sk.setAnimation(0, anim, false);
                        } else {
                            sk.addAnimation(0, anim, false, 0);
                        }
                    }

                    game.scheduleOnce(() => reels?.[b.col]?.playMultiplierCollect(b.row), (i + lead) * ANIM_SEC);
                });

                game.scheduleOnce(() => {
                    if (sk?.node?.isValid) {
                        sk.node.active = false;
                    }

                    resolve();
                }, finishDelay);
            })
        );
    });

    if (hasMulValue) {
        game.scheduleOnce(() => {
            if (!abort.aborted) game.showWinBarMul(game.winBarMulValue, isFg);
        }, 0.2);
    }

    balls.forEach((b, i) => {
        game.scheduleOnce(
            () => {
                if (abort.aborted) return;
                game.winBarMulValue += b.val;
                game.showWinBarMul(game.winBarMulValue, isFg);
            },
            (i + lead) * ANIM_SEC + 0.2
        );
    });

    game.scheduleOnce(() => {
        if (abort.aborted) return;
        game.winBarMulValue = acc;
        game.setWinBarMul(acc);

        if (isFg) {
            game.setTotalMultiplierLabel(acc);
        }

        game.playWinBarAdd(finalNum);
    }, finishDelay);

    await Promise.all(tasks);
}

/** 新曲射版本 */
async function runCollectWinWithFlyEffect(
    game: ISlotGameMain<GameViewAdapter>,
    balls: CollectBall[],
    hasMulValue: boolean,
    acc: number,
    isFg: boolean,
    finalNum: number,
    abort: CollectAbort
): Promise<void> {
    // 因為要吃 turbo 加速縮放 真實時間量測不正確改用 game time
    let lastLaunchDuration: number | null = null;

    if (hasMulValue) {
        await new Promise<void>((resolve) => {
            game.scheduleOnce(() => {
                if (!abort.aborted) game.showWinBarMul(game.winBarMulValue, isFg);
                game.scheduleOnce(resolve, 0);
            }, 0.2);
        });
        if (abort.aborted) return;

        const tasks: Promise<void>[] = [];
        let duration = 0;

        game.forEachView((v) => {
            // frame_total_multiplier → winBarMulNode
            duration = Math.max(duration, resolveCollectFlyDuration(v));
            tasks.push(playCollectMulFly(v));
        });

        lastLaunchDuration = duration;

        await Promise.all(tasks);
        if (abort.aborted) return;
    }

    for (const b of balls) {
        // 維持跟上一顆相同的開始間隔
        if (lastLaunchDuration !== null) {
            const remain = ANIM_SEC - lastLaunchDuration;

            if (remain > 0) {
                await new Promise<void>((resolve) => {
                    game.scheduleOnce(resolve, remain);
                });
                if (abort.aborted) return;
            }
        }

        // 先更新倍率，讓目標位置正確
        game.winBarMulValue += b.val;
        game.showWinBarMul(game.winBarMulValue, isFg);

        // 等 winBarMulNode 更新位置
        await new Promise<void>((resolve) => {
            game.scheduleOnce(resolve, 0);
        });
        if (abort.aborted) return;

        const tasks: Promise<void>[] = [];
        let duration = 0;

        game.forEachView((v) => {
            v.slotMachineView?.reelViews?.[b.col]?.playMultiplierCollect(b.row);
            duration = Math.max(duration, resolveCollectFlyDuration(v, { col: b.col, row: b.row }));

            tasks.push(
                playCollectMulFly(v, {
                    col: b.col,
                    row: b.row
                })
            );
        });

        lastLaunchDuration = duration;

        // 這顆飛完才處理下一顆
        await Promise.all(tasks);
        if (abort.aborted) return;
    }

    // 三段速度各自額外加碼 一般快速急速分別是 1s 0.5s 0.2s 加在合併進總分前 讓最終倍率多停留一下
    await new Promise<void>((resolve) => game.scheduleOnce(resolve, game.cascadeTiming().mulHoldExtra));
    if (abort.aborted) return;

    game.winBarMulValue = acc;
    game.setWinBarMul(acc);

    if (isFg) {
        game.setTotalMultiplierLabel(acc);
    }

    game.playWinBarAdd(finalNum);
}

/**
 * 目前唯一的贏分演出策略：直接委派給 runCollectWin（倍率球收球演出本體）。
 * 實作 IWinPerformStrategy 只是把既有邏輯包成可替換的策略物件，行為與搬移前完全一致；
 * skip/reset 本階段先不實作（entry 目前用 game.win.winPhaseSkipFn 手動處理跳過動畫，
 * 尚未收斂進此介面，見 IWinPerformStrategy 的說明）。
 */
export class MultiplierCollectWinStrategy implements IWinPerformStrategy<ISlotGameMain<GameViewAdapter>> {
    public play(game: ISlotGameMain<GameViewAdapter>, ...args: unknown[]): Promise<void> {
        const [cols, acc, isFg, finalNum] = args as [number[][], number, boolean, number];

        return runCollectWin(game, cols, acc, isFg, finalNum);
    }
}

/** 對應 SGTask_WinAnimation（倍率球收集）。addTask() 到頂層佇列時用這個薄殼。 */
export class CollectWinTask extends GameTask {
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly cols: number[][],
        private readonly acc: number,
        private readonly isFg: boolean,
        private readonly finalNum: number,
        private readonly strategy: IWinPerformStrategy<
            ISlotGameMain<GameViewAdapter>
        > = new MultiplierCollectWinStrategy()
    ) {
        super();
    }

    protected onStart(): void {
        this.strategy
            .play(this.game, this.cols, this.acc, this.isFg, this.finalNum)
            .catch((error) => console.warn('[CollectWinTask] failed', error))
            .finally(() => this.finish());
    }
}
